// ManyChat Standard interno 2026 — naming ai_msg_*
// v3 — Lee output JSON del Formatter (gpt-4o-mini) + COMPACTA partes no-vacías
//
// Diferencia vs v2: si el formatter llena parte1+parte3 saltando parte2,
// compactamos las partes no-vacías y las asignamos sequencialmente a ai_msg_1/2/3.
// Eso evita que ManyChat haga skip del mensaje del medio.

const inp = $input.first().json;

// El output del nodo OpenAI Chat puede venir en:
//   - .message.content (string JSON)
//   - .content (string JSON)
//   - directamente como objeto parseado
let parsed = {};
const raw = inp.message?.content ?? inp.content ?? inp;

try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : (raw && typeof raw === 'object' ? raw : {});
} catch (e) {
  // Fallback: si el formatter devuelve mal el JSON, asignar todo a parte1
  parsed = { parte1: typeof raw === 'string' ? raw : String(raw), parte2: '', parte3: '' };
}

// Compactar partes no-vacías en orden (descartar empties intermedios)
const allParts = [parsed.parte1, parsed.parte2, parsed.parte3]
                   .map(p => String(p || '').trim())
                   .filter(p => p.length > 0);

const ai_msg_1 = allParts[0] || '';
const ai_msg_2 = allParts[1] || '';
const ai_msg_3 = allParts[2] || '';
const ai_msg_count = allParts.length || 1;

// Conservar el output crudo del AI Agent (pre-formatter) para auditoría
const rawOriginal = $('AI Agent').first().json.output || '';

return [{
  json: {
    raw: rawOriginal,
    ai_msg_1,
    ai_msg_2,
    ai_msg_3,
    ai_msg_count,
    subscriber_id: $('Normalize Payload').first().json.subId
  }
}];

// v0.7 — Inyecta [CONTEXTO TURNO] al user message usando el STATE PERSISTIDO en Supabase.
// Reemplaza los valores hardcodeados (perfil/etapa/datos/productos) por los reales
// leídos de sys_session_state (vía nodo "Get session_state" inmediatamente anterior).
// Fix de Capa 1 del plan de re-saludo y re-pregunta.
//
// Referencia por NOMBRE de nodo (no $json) porque entre este nodo y el AI Agent
// está el nodo "Get a document" que rompe el flujo de $json
// (ver _core/standards/n8n-data-references.md).

const data = $input.first().json;
const stateRow = $('Get session_state').first()?.json || {};

const fecha = new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });

const perfil   = stateRow.perfil   || 'sin clasificar';
const etapa    = stateRow.etapa    || 'bienvenida';
const datos    = stateRow.datos_capturados || {};
const productos = Array.isArray(stateRow.productos_mostrados) ? stateRow.productos_mostrados : [];

const datosLine = Object.keys(datos).length
  ? JSON.stringify(datos)
  : '(sin datos del lead aún)';
const productosLine = productos.length
  ? productos.join(', ')
  : '(ninguno todavía)';

const numeroCanal = (data.channel === 'wa' && data.phone) ? data.phone : null;
const lineaNumero = numeroCanal
  ? `\n- Número del canal (WhatsApp): ${numeroCanal}`
  : '';

const contextoTurno = `[CONTEXTO TURNO]
- Canal: ${data.canalLabel}${lineaNumero}
- Fecha y hora actual: ${fecha}
- Perfil del lead: ${perfil}
- Etapa actual: ${etapa}
- Datos ya capturados: ${datosLine}
- Productos ya mostrados: ${productosLine}

[MENSAJE DEL USUARIO]
${data.mensajeActual}`;

return [{
  json: {
    ...data,
    userMessage: contextoTurno,
    _state: stateRow
  }
}];

// Alinea con el contrato de Flow A (sección 1.2).
// Payload esperado: { subscriber_id, channel, first_name, last_input_text }
// v0.6 dedup: compara mensaje actual contra último mensaje human en memoria.
// Si son idénticos → skip=true (evita duplicados por reintentos de webhook de ManyChat).

const body = $('Webhook (ManyChat)').first().json.body || $('Webhook (ManyChat)').first().json;

const channel = (body.channel || 'test').toLowerCase();     // 'wa' | 'ig' | 'fb' | 'test'
const phone = String(body.phone || body.whatsapp_phone || body.telefono || '').trim();
const subId = String(body.subscriber_id || body.from || 'anon');
const sessionKey = `${channel}_${subId}`;                   // sessionKey para memoria Postgres
const mensajeActual = String(body.last_input_text || body.mensaje || body.text || '').trim();

// Extraer último mensaje human de la memoria (viene wrapped con [CONTEXTO TURNO] + [MENSAJE DEL USUARIO]).
const lastFromMemory = String($('Get last user message').first().json.last_content || '');
const userMsgMatch = lastFromMemory.match(/\[MENSAJE DEL USUARIO\]\s*\n([\s\S]*)$/);
const lastUserMsg = (userMsgMatch ? userMsgMatch[1] : lastFromMemory).trim();

// Determinar skip: vacío, o duplicado exacto del último mensaje.
if (!mensajeActual) {
  return [{ json: { skip: true, reason: 'empty_message' } }];
}
if (lastUserMsg && lastUserMsg === mensajeActual) {
  return [{ json: { skip: true, reason: 'duplicate_message', sessionKey, mensajeActual } }];
}

const canalLabel = channel === 'wa' ? 'WhatsApp'
                 : channel === 'ig' ? 'Instagram'
                 : channel === 'fb' ? 'Facebook'
                 : 'Test';

return [{
  json: {
    skip: false,
    channel,
    phone,
    canalLabel,
    subId,
    sessionKey,
    mensajeActual,
    firstName: body.first_name || '',
    timestamp: body.timestamp || new Date().toISOString()
  }
}];

